"""N-296: cross-tier rule for an explicit Sig in a merge's per-input args
(additional_contract_input_args): a Sig slot the primary call left auto-signed
(None) is ALWAYS signed by the connected signer for each additional contract
input; a caller-supplied value in that slot is overwritten (TS reference).

Proves: on the inputs of conformance/sdk-call/stateful-merge-prepared.json,
call() with (a) no per-input args and (b) an explicit garbage Sig in the
per-input args broadcasts a tx byte-equal to REFERENCE_TX_HEX (derived by the
TS SDK, Spend-validated on all three inputs by its MockProvider).

Does NOT prove: the other tiers (own tests, same constant), non-Sig slots, or
a live node.
"""

from __future__ import annotations

import json
from pathlib import Path

from runar.sdk.contract import RunarContract
from runar.sdk.local_signer import LocalSigner
from runar.sdk.provider import MockProvider
from runar.sdk.types import CallOptions, RunarArtifact, Utxo

VECTOR_PATH = (
    Path(__file__).resolve().parents[3]
    / "conformance" / "sdk-call" / "stateful-merge-prepared.json"
)

REFERENCE_TX_HEX = ""


def _utxo(d: dict) -> Utxo:
    return Utxo(txid=d["txid"], output_index=d["outputIndex"], satoshis=d["satoshis"], script=d["script"])


def _merge(per_input_args):
    v = json.loads(VECTOR_PATH.read_text())
    art = RunarArtifact.from_dict(v["artifact"])
    signer = LocalSigner(v["privKeyHex"])
    provider = MockProvider("testnet")
    provider.add_utxo(signer.get_address(), _utxo(v["fundingUtxo"]))
    cu = _utxo(v["contractUtxo"])
    eu = _utxo(v["extraContractUtxo"])
    provider.add_contract_utxo(cu.script, cu)
    provider.add_contract_utxo(eu.script + ":extra", eu)
    contract = RunarContract.from_utxo(art, cu)
    contract.connect(provider, signer)
    contract.call(
        v["method"], [None], provider, signer,
        CallOptions(
            additional_contract_inputs=[eu],
            new_state={"count": 1},
            additional_contract_input_args=per_input_args,
        ),
    )
    txs = provider.get_broadcasted_txs()
    assert len(txs) == 1
    return txs[0]


def test_n296_merge_default_path_matches_reference():
    assert _merge(None) == REFERENCE_TX_HEX


def test_n296_merge_explicit_sig_is_overwritten_by_signer():
    assert _merge([["ab" * 71]]) == REFERENCE_TX_HEX
